definition.script:
pipeline {
  agent { label 'linux' }

  options {
    timestamps()
    disableConcurrentBuilds()
    timeout(time: 20, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '20'))
  }

  triggers {
    cron('H */6 * * *')
  }

  environment {
    NEXUS_BASE_URL = 'http://nexus:8081'
  }

  stages {
    stage('Reclaim Nexus disk') {
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-admin', usernameVariable: 'NEXUS_ADMIN_USER', passwordVariable: 'NEXUS_ADMIN_PASSWORD')]) {
          sh '''
            set -e
            python3 - <<'PY'
import base64
import json
import os
import time
import urllib.error
import urllib.request

base = os.environ["NEXUS_BASE_URL"]
auth = base64.b64encode((os.environ["NEXUS_ADMIN_USER"] + ":" + os.environ["NEXUS_ADMIN_PASSWORD"]).encode()).decode()

def call(method, path, body=None):
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(base + path, data=data, method=method,
        headers={"Authorization": "Basic " + auth, "Content-Type": "application/json", "Accept": "application/json"})
    try:
        r = urllib.request.urlopen(req, timeout=60)
        raw = r.read().decode()
        return r.status, (json.loads(raw) if raw.strip() else None)
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()

def blobstore_gb():
    st, bs = call("GET", "/service/rest/v1/blobstores")
    for b in bs or []:
        if b.get("name") == "default":
            return b.get("totalSizeInBytes", 0) / 1e9, b.get("availableSpaceInBytes", 0) / 1e9
    return 0.0, 0.0

def components():
    tok, n = None, 0
    while True:
        p = "/service/rest/v1/components?repository=docker-hosted"
        if tok:
            p += "&continuationToken=" + tok
        st, d = call("GET", p)
        n += len(d.get("items", []))
        tok = d.get("continuationToken")
        if not tok:
            return n

used0, avail0 = blobstore_gb()
print("Before: blobstore %.2f GB used, %.2f GB free, %d docker-hosted components" % (used0, avail0, components()))

st, d = call("GET", "/service/rest/v1/tasks")
tasks = d.get("items", [])

def run_task(pred, label):
    cand = [t for t in tasks if pred(t)]
    if not cand:
        print("WARN: no task matched for " + label + " (skipped)")
        return
    tid = cand[0]["id"]
    s, _ = call("POST", "/service/rest/v1/tasks/" + tid + "/run")
    print("Triggered %s (%s) -> HTTP %s" % (label, cand[0]["name"], s))
    for _ in range(60):
        time.sleep(10)
        s, info = call("GET", "/service/rest/v1/tasks/" + tid)
        if isinstance(info, dict) and info.get("currentState") == "WAITING" and info.get("lastRunResult"):
            print("  %s finished: %s" % (label, info.get("lastRunResult")))
            return
    print("  %s still running after poll window (Nexus continues it server-side)" % label)

# Order matters: apply retention policies first (soft-delete expired
# versions), then reclaim the now-unreferenced docker blobs.
run_task(lambda t: t["type"] == "repository.cleanup", "Cleanup service")
run_task(lambda t: t["type"] == "assetBlob.cleanup" and "docker" in t["name"].lower(), "Cleanup unused docker blobs")

used1, avail1 = blobstore_gb()
print("After:  blobstore %.2f GB used, %.2f GB free, %d docker-hosted components" % (used1, avail1, components()))
print("Reclaimed ~%.2f GB" % max(0.0, used0 - used1))
PY
          '''
        }
      }
    }
  }
}
